const API = require('./api.js');

// At some point, I destroyed all the imports during the refactor. I thought about re-importing the classes, but... leaving just 'rooms' feels kind of hilarious 🤷‍♂️
const Room = require('./Room.js');
const WS = require('./ws.js');
const EventEmitter = require('events');
/**
 * Version Update:
 * This release is a major refactor. The previous codebase was a bit of a chaotic 
 * masterpiece—early versions were built for speed and "debugging by proximity," 
 * with references everywhere and quite a bit of clutter. We now have a solid 
 * architecture and a clear vision for how this library should evolve.
 * 
 * We've also finally implemented several features that were previously "documentation-only." 
 * It turns out that writing about a feature in the docs doesn't actually make it 
 * appear in the code by magic. Who would have thought?
 */

// Yeah, I know, "stuff happens" here. I'll fix it in a future commit... maybe... 🙄
class UsersService {
  constructor(imvu) {
    this.imvu = imvu;
    this.cache = new Map();
  }

  initializeCache(users) {
    users.forEach(data => {
      const user = new User(data, this.imvu);
      this.cache.set(user.id, user);
    });
  }

  get(query = {}) {
    const users = [...this.cache.values()];
    return Object.keys(query).length
      ? users.filter(u => Object.keys(query).every(k => u[k] === query[k]))
      : users;
  }

  getById(id) {
    return this.cache.get(id) || null;
  }

  addJson(data) {
    const id = data.id || data.legacy_cid;
    let user = this.getById(id);
    if (!user) {
      user = new User(data, this.imvu);
      this.add(user);
    }
    return user;
  }

  add(user) {
    if (!this.cache.has(user.id)) {
      this.cache.set(user.id, user);
      this.imvu.emit('join', user);
    }
    return user;
  }

  remove(userId) {
    const user = this.cache.get(userId);
    if (!user) return;

    if (user.furniture) {
      user.furniture.removeUser(user, user.seatId);
    }

    this.imvu.emit('leave', user);
    this.cache.delete(userId);
  }
}



class User {
  constructor(data, imvu) {
    this.created = data.created || null;
    this.registered = data.registered || null;
    this.gender = data.gender || null;
    this.display_name = data.display_name || null;
    this.age = data.age || null;
    this.country = data.country || null;
    this.state = data.state || null;
    this.avatar_image = data.avatar_image || null;
    this.avatar_portrait_image = data.avatar_portrait_image || null;
    this.is_vip = data.is_vip || false;
    this.is_ap = data.is_ap || false;
    this.is_ap_plus = data.is_ap_plus || false;
    this.is_ap_plus_founder = data.is_ap_plus_founder || false;
    this.is_creator = data.is_creator || false;
    this.is_adult = data.is_adult || false;
    this.is_ageverified = data.is_ageverified || false;
    this.is_staff = data.is_staff || false;
    this.is_greeter = data.is_greeter || false;
    this.greeter_score = data.greeter_score || 0;
    this.badge_level = data.badge_level || 0;
    this.username = data.username || null;
    this.relationship_status = data.relationship_status || null;
    this.orientation = data.orientation || null;
    this.looking_for = data.looking_for || null;
    this.interests = data.interests || null;
    this.legacy_cid = data.legacy_cid || null;
    this.persona_type = data.persona_type || null;
    this.availability = data.availability || null;
    this.is_discussion_moderator = data.is_discussion_moderator || false;
    this.online = data.online || false;
    this.tagline = data.tagline || null;
    this.thumbnail_url = data.thumbnail_url || null;
    this.is_host = data.is_host || 0;
    this.has_nft = data.has_nft || false;
    this.vip_tier = data.vip_tier || 0;
    this.vip_platform = data.vip_platform || null;
    this.has_legacy_vip = data.has_legacy_vip || false;
    this.isMod = data.isMod || false;
    this.bot = data.bot || false;
    this.furniture = null;
    this.seatId = null;
    this.imvu = imvu;
    this.id = data.id || this.legacy_cid;


    if (data.furnitureInstanceId) {
      this.observeFurniture(data.furnitureInstanceId);
    }


  }

  kick() {
    this.imvu.ws.send({ "type": "kick", "user": this.id })
  }

  say(message) {
    this.imvu.ws.send({ "type": "say", "content": message, "user": this.id })
  }

  send(message) {
    this.say(message)
  }

  observeFurniture(furnitureInstanceId, seatId = null) {
    const prevFurniture = this.furniture;
    const prevSeatId = this.seatId;

    const instanceId = Number.isInteger(furnitureInstanceId)
      ? furnitureInstanceId
      : -1;

    let nextFurniture = this.imvu.furnitures.getById(instanceId);

    if (!nextFurniture) {
      // If it's not here, it doesn't exist. Unless we just make it up. Magic! ✨
      nextFurniture = this.imvu.furnitures.addJson({
        instance_id: instanceId
      })
    }

    const nextSeatId = seatId;

    const changed =
      prevFurniture?.instance_id !== nextFurniture.instance_id ||
      prevSeatId !== nextSeatId;

    if (!changed) return;

    // salir del furniture anterior
    if (prevFurniture) {
      prevFurniture.removeUser(this, prevSeatId);
    }

    // entrar al nuevo
    this.furniture = nextFurniture;
    this.seatId = nextSeatId;
    nextFurniture.addUser(this, nextSeatId);

    this.imvu.emit('seat', {
      seat_id: nextSeatId,
      seat: nextFurniture,
      leave: {
        furniture: prevFurniture,
        seat_id: prevSeatId
      },
      user: this
    });
  }


}


class FurnituresService {
  constructor(imvu) {
    this.imvu = imvu;
    this.cache = new Map();
  }

  initializeCache(furnitures) {
    furnitures.forEach(data => {
      const furniture = new Furniture(data, this.imvu);
      this.cache.set(furniture.instance_id, furniture);
    });
    // For the minimalists who think chairs are too mainstream. Welcome to the 'Standing on Air' club. 🕴️
    this.addJson({ instance_id: -1 });

  }

  get(query = {}) {
    const furnitures = [...this.cache.values()];
    return Object.keys(query).length
      ? furnitures.filter(u => Object.keys(query).every(k => u[k] === query[k]))
      : furnitures;
  }

  getById(instanceId) {
    return this.cache.get(instanceId) || null;
  }


  addJson(data) {
    const id = data.instance_id;
    let furniture = this.getById(id);
    if (!furniture) {
      furniture = new Furniture(data, this.imvu);
      this.add(furniture);
    }
    return furniture;
  }

  add(furniture) {
    if (!this.cache.has(furniture.instance_id)) {
      this.cache.set(furniture.instance_id, furniture);
    }
    return furniture;
  }

  remove(instanceId) {
    const furniture = this.cache.get(instanceId);
    if (!furniture) return;
    this.cache.delete(instanceId);
  }

}

class Furniture {
  constructor(data, imvu) {
    this.asset_url = data.asset_url || '';
    this.instance_id = data.instance_id || null;
    this.id = this.instance_id;
    this.node = data.node || 'furniture.Floor.01';
    this.x = data.x || 0;
    this.y = data.y || 0;
    this.z = data.z || 0;
    this.updated = data.updated || true;
    this.yaw = data.yaw || 0;
    this.pitch = data.pitch || 0;
    this.roll = data.roll || 0;
    this.scale = data.scale || 1;
    this.lock = data.lock || false;
    this.use = data.use || 'none';
    this.sync_seat_stances = data.sync_seat_stances || false;
    this.sync_prop_actions = data.sync_prop_actions || false;
    this.product_id = data.product_id || null;
    this.users = new Map();
    this.imvu = imvu;
  }

  addUser(user, seatId) {
    if (!this.users.has(seatId)) {
      this.users.set(seatId, user);
    }
  }

  removeUser(user, seatId) {
    if (this.users.get(seatId) === user) {
      this.users.delete(seatId);
    }
  }

  async set(newData) {
    if (!newData || typeof newData !== 'object') {
      throw new Error('newData should be an object');
    }

    if (newData.users) {
      this.users = new Map(Object.entries(newData.users).map(([seatId, userData]) => [
        seatId,
        this.imvu.users.addJson(userData)
      ]));
    }

    Object.assign(this, newData);

    this.updated = false;
    const furnitureToSend = { ...this };
    // Delete the evidence before sending it to the server 🕵️‍♂️
    delete furnitureToSend.imvu;
    delete furnitureToSend.users;
    this.imvu.emit('furniture_set', furnitureToSend);

    return true;
  }

  move(seat) {
    this.imvu.ws.send({ "type": "move", "seat": { "instance_id": this.instance_id, "seat_id": seat ? seat : 0 } })
  }

}


class IMVU extends EventEmitter {
  constructor(options) {
    super();
    this.api = new API();
    this.name = options.name || 'defaultbot';
    this.walk = options.walk || false;
    this.gameslib = options.gameslib || false;
    this.outfit = options.outfit || [];
    this.room = null;
    this.ws = new WS(this, options.bot);

    // No time to make this look fancy, sorry!
    this.say = message => this.ws.send({ "type": "say", "content": message })
    this.send = this.say
    this.users = new UsersService(this);
    this.furnitures = new FurnituresService(this);
    this.seat = null;

    // This is already deprecated, I added it at some point just to keep track of the ws, 
    // I left it because it might be useful for the user and because it was already written - 
    // writing this comment took longer than just removing it
    this.auth = false;
  }

  static User = User;
  static Furniture = Furniture;
  static Room = Room;

  async login(token) {
    try {
      const userData = await this.api.authenticate(token);

      this.ws.connect(userData);
      this.display_name = userData.display_name;
      this.id = userData.id;
      this.room = new Room(userData.room, this);

      // Too lazy for this now, I'll fix it in another commit... I swear
      this.room.say = this.say;
      this.room.send = this.say;

      try {
        await Promise.all([
          this.users.initializeCache(userData.room.users),
          this.furnitures.initializeCache(userData.room.furnitures)
        ]);

        this.emit('ready');
        this.auth = true;
      } catch (error) {
        console.error('Error al inicializar cachés:', error);
        throw error;
      }
    } catch (error) {
      console.error('Failed to login:', error);
      throw error;
    }

    if (this.seat) {
      this.update_seat(this.seat)
    }

  }

  update_seat(seat) {
    this.ws.send({ "type": "update_seat", "seat": this.seat })
  }
}

module.exports = IMVU;
